# frozen_string_literal: true
# Applied by template.rb when SCAFFOLD_TEST=minitest (the default).
# Rails' own test scaffold (Minitest + Capybara + selenium-webdriver) is
# generated by `rails new` unless --skip-test was passed, so this only adds
# role/user fixtures on top of it.

auth = ENV.fetch("SCAFFOLD_AUTH", "clearance")

after_bundle do
  create_file "test/fixtures/roles.yml", force: true do
    <<~YAML
      member:
        name: member

      moderator:
        name: moderator

      admin:
        name: admin
    YAML
  end

  # `generate model RoleAssignment` (in roles.rb) auto-generates a stub
  # test/fixtures/role_assignments.yml referencing labels ("user: one",
  # "role: one") that don't exist in the roles.yml/users.yml fixtures
  # above — `fixtures :all` fails with a foreign key violation unless this
  # is overwritten to reference labels that actually exist.
  create_file "test/fixtures/role_assignments.yml", force: true do
    <<~YAML
      member:
        user: member
        role: member

      moderator:
        user: moderator
        role: moderator

      admin:
        user: admin
        role: admin
    YAML
  end

  if auth == "clearance"
    # Fixtures are inserted directly via SQL and bypass ActiveRecord
    # callbacks entirely, including Clearance's before_create that normally
    # generates remember_token — so it has to be set explicitly here, or
    # `fixtures :all` raises a NOT NULL violation on that column.
    create_file "test/fixtures/users.yml", force: true do
      <<~YAML
        member:
          email: member@example.com
          encrypted_password: <%= BCrypt::Password.create(User::DEFAULT_PASSWORD, cost: BCrypt::Engine::MIN_COST) %>
          remember_token: <%= Clearance::Token.new %>

        moderator:
          email: moderator@example.com
          encrypted_password: <%= BCrypt::Password.create(User::DEFAULT_PASSWORD, cost: BCrypt::Engine::MIN_COST) %>
          remember_token: <%= Clearance::Token.new %>

        admin:
          email: admin@example.com
          encrypted_password: <%= BCrypt::Password.create(User::DEFAULT_PASSWORD, cost: BCrypt::Engine::MIN_COST) %>
          remember_token: <%= Clearance::Token.new %>
      YAML
    end

    inject_into_file "test/test_helper.rb", after: "class ActiveSupport::TestCase\n" do
      "  fixtures :all\n"
    end

    append_to_file "test/test_helper.rb" do
      <<~RUBY

        class ActionDispatch::IntegrationTest
          def sign_in_as(user)
            token = SecureRandom.hex(20)
            user.update_columns(remember_token: token)
            cookies[Clearance.configuration.cookie_name] = token
          end
        end
      RUBY
    end
  else
    create_file "test/fixtures/users.yml", force: true do
      <<~YAML
        member:
          email: member@example.com
          encrypted_password: <%= Devise::Encryptor.digest(User, "correct-horse-battery") %>

        moderator:
          email: moderator@example.com
          encrypted_password: <%= Devise::Encryptor.digest(User, "correct-horse-battery") %>

        admin:
          email: admin@example.com
          encrypted_password: <%= Devise::Encryptor.digest(User, "correct-horse-battery") %>
      YAML
    end

    inject_into_file "test/test_helper.rb", after: "class ActiveSupport::TestCase\n" do
      "  fixtures :all\n"
    end

    append_to_file "test/test_helper.rb" do
      <<~RUBY

        class ActionDispatch::IntegrationTest
          include Warden::Test::Helpers

          def sign_in_as(user)
            login_as(user, scope: :user)
          end
        end
      RUBY
    end
  end
end
